mkdir -p /app/w && cat > /app/w/bs.py <<'EOF'
import numpy as np, itertools, json, sys
N=6
def places(L):
    out=[]
    for r in range(N):
        for c in range(N):
            if c+L<=N: out.append((0,frozenset((r,c+i) for i in range(L))))
            if r+L<=N and L>1: out.append((1,frozenset((r+i,c) for i in range(L))))
    return out
def nb(s):
    return {(r+dr,c+dc) for r,c in s for dr in(-1,0,1) for dc in(-1,0,1)}
lays=[];
for a in places(4):
  for b in places(3):
    if a[1]&b[1]: continue
    for d in places(2):
      if d[1]&(a[1]|b[1]): continue
      lays.append((a,b,d))
M=len(lays); print(M)
occ=np.zeros((M,36),bool); R=np.zeros((M,6),bool)
edge=lambda s:any(r in(0,5) or c in(0,5) for r,c in s)
cen={(2,2),(2,3),(3,2),(3,3)}
for i,(a,b,d) in enumerate(lays):
    S=[a[1],b[1],d[1]]
    for s in S:
        for r,c in s: occ[i,r*6+c]=1
    tch=lambda x,y: bool(nb(x)&y)
    R[i,0]=1
    R[i,1]=not(tch(S[0],S[1]) or tch(S[0],S[2]) or tch(S[1],S[2]))
    R[i,2]=a[0]==b[0]==d[0]
    R[i,3]=all(edge(s) for s in S)
    R[i,4]=not any(s&cen for s in S)
    R[i,5]=all(any(tch(S[j],S[k]) for k in range(3) if k!=j) for j in range(3))
print(R.sum(0))
np.savez('/app/w/lay.npz',occ=occ,R=R)
EOF
python3 /app/w/bs.py

