arguments.command:
cat > /app/w/post.py <<'EOF'
import numpy as np, json, sys
d=np.load('/app/w/lay.npz'); occ=d['occ']; R=d['R'].astype(float)
n=R.sum(0); prior=(R/n).sum(1)/6
hist=json.load(open('/app/w/hist.json')) if len(sys.argv)<2 else []
rowc=np.stack([occ[:,r*6:(r+1)*6].sum(1) for r in range(6)],1)
colc=np.stack([occ[:,c::6].sum(1) for c in range(6)],1)
def scanlik(true,rep):
    p=np.zeros(len(true))
    for dd,pp in((-1,.15),(0,.7),(1,.15)):
        p+=pp*(np.clip(true+dd,0,6)==rep)
    return p
def lik(a):
    if a[0]=='fire': h=occ[:,a[1]*6+a[2]]; return np.where(h==a[3],.9,.1)
    t=(rowc if a[0]=='row' else colc)[:,a[1]]; return scanlik(t,a[2])
w=prior.copy()
for a in hist: w*=lik(a)
w/=w.sum()
def H(p): p=np.clip(p,1e-12,1); return -(p*np.log(p)).sum()
def Hb(q): q=np.clip(q,1e-12,1-1e-12); return -(q*np.log(q)+(1-q)*np.log(1-q)).sum()
def summ(w):
    # rule posterior: P(rule r|data) ∝ sum_i w_i * contribution of rule r
    pr=(R/n)*(w/prior)[:,None]; pr=pr.sum(0); pr/=pr.sum()
    return pr, occ.T@w
def unc(w):
    pr,c=summ(w); return H(pr)/np.log(6)+Hb(c)/20.1236
pr,c=summ(w)
print('rules',np.round(pr,3)); print(np.round(c.reshape(6,6),2))
if len(sys.argv)>1 and sys.argv[1]=='final':
    json.dump({'rules':pr.tolist(),'occ':c.reshape(6,6).tolist()},open('/app/w/final.json','w'));sys.exit()
u0=unc(w); res=[]
for cell in range(36):
    h=occ[:,cell]; eu=0
    for o in(0,1):
        l=np.where(h==o,.9,.1); ww=w*l; po=ww.sum(); eu+=po*unc(ww/po)
    res.append(((u0-eu)/1,'fire',cell//6,cell%6))
for ax,T in(('row',rowc),('col',colc)):
    for k in range(6):
        eu=0
        for o in range(7):
            ww=w*scanlik(T[:,k],o); po=ww.sum()
            if po>1e-12: eu+=po*unc(ww/po)
        res.append(((u0-eu)/2,ax,k,None))
res.sort(reverse=True)
for r in res[:6]: print(r)
EOF
